import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"UIX Forge","description":"Learn about UIX Forge, a powerful custom element that combines templates, sparks, and UIX styling.","frontmatter":{"title":"UIX Forge","description":"Learn about UIX Forge, a powerful custom element that combines templates, sparks, and UIX styling."},"headers":[],"relativePath":"en/projects/uix/forge/index.md","filePath":"en/projects/uix/forge/index.md","lastUpdated":1793023597000}'),n={name:"en/projects/uix/forge/index.md"};function i(s,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><div class="info custom-block"><p class="custom-block-title">UIX 9.0.0-beta.2 preview</p><p>This Forge content follows the reviewed <code>dev</code> revision, separate from the stable 8.4.0 baseline.</p></div><p>UIX Forge lets you use templates anywhere in a Home Assistant element&#39;s configuration, then add behaviours with <a href="./sparks/">UIX Forge Sparks</a> and style the result with UIX. It can also keep templates that belong to the wrapped card or badge—such as Markdown content or native visibility—so Home Assistant evaluates them normally.</p><p>In YAML, put the wrapped element&#39;s own configuration in <a href="./forge#keep-the-elements-configuration-in-element_base"><code>element_base</code></a> when it needs to be passed through unchanged, and put the values Forge should change in <code>element</code>.</p><p>Forge supports the card, badge, row, picture-element, section, footer, and card-feature molds. Cross-context molds allow embedding one element type in a different parent context, such as a card used as a row inside an entities card — see <a href="./forge#cross-context-molds">Cross-context molds</a>. The <code>element_base</code>/<code>element</code> layout works with every mold.</p><p>See <a href="./forge">Forge</a> for complete forge config reference.</p><h2 id="foundries" tabindex="-1">Foundries <a class="header-anchor" href="#foundries" aria-label="Permalink to &quot;Foundries&quot;">​</a></h2><p>A <strong>foundry</strong> is a reusable UIX Forge configuration: save <code>forge</code>, <code>element</code>, and <code>element_base</code> blocks once, then reuse them across many cards. A Foundry <code>element_base</code> is editor-preserved source. Save it from the Forge editor&#39;s Export YAML and retain it when editing the Foundry, so that Native configuration remains available for future visual-editor support. <code>element_disabled_paths</code> remains local to each Forge that uses the Foundry.</p><p>See <a href="./foundries">Foundries</a> for a full guide including merge behaviour, nested foundries, and management via the integration options.</p><h2 id="sparks" tabindex="-1">Sparks <a class="header-anchor" href="#sparks" aria-label="Permalink to &quot;Sparks&quot;">​</a></h2><p>Sparks are optional behaviours that you add to the <code>forge.sparks</code> list. Each spark has a <code>type</code> key and its own options.</p><p>Available sparks:</p><ul><li>💬 <a href="./sparks/tooltip">Tooltip</a> — attach a styled tooltip to any element inside the forged element.</li><li>:material-button-cursor: <a href="./sparks/button">Button</a> - attach a styled button (<code>ha-button</code>) with actions as a sibling before or after any element within the forged element.</li><li>:material-badge-account-horizontal-outline: <a href="./sparks/badge">Badge</a> - insert a Web Awesome-styled <code>uix-badge</code> as a sibling before or after any element within the forged element.</li><li>🏷️ <a href="./sparks/attribute">Attribute</a> — add, replace or remove an attribute of any element within the forged element.</li><li>⚡ <a href="./sparks/event">Event</a> — receive DOM events from <code>fire-dom-event</code> actions and expose their data as template variables.</li><li>⭐ <a href="./sparks/tile-icon">Tile Icon</a> — insert a <code>ha-tile-icon</code> element as a sibling before or after any element within the forged element.</li><li>🛡️ <a href="./sparks/state-badge">State badge</a> - insert a <code>state-badge</code> element as a sibling before or after any element within the forged element.</li><li>:material-grid: <a href="./sparks/grid">Grid</a> - apply <strong>CSS Grid</strong> layout to any container element inside a forged element</li><li>🔍 <a href="./sparks/search">Search</a> - queries a container within a forged element with a CSS selector and optional inner text to find, then apply mutations to the found element(s).</li><li>:material-map: <a href="./sparks/map">Map</a> — preserve the map view and add tours, history sliders, and entity filters with configurable control positions.</li><li>:material-lock: <a href="./sparks/lock">Lock</a> — overlay a lock icon on any element to block interaction until the user passes a PIN, passphrase, or confirmation challenge.</li><li>:material-form-select: <a href="./sparks/form">Form</a> — add a Home Assistant form and optional submit and clear actions to a forged element.</li><li>:material-star-four-points-outline: <a href="./sparks/overlay-icon">Overlay Icon</a> — overlay a <code>ha-icon</code>/<code>ha-state-icon</code> on any element inside the forged element.</li><li>:material-image-outline: <a href="./sparks/background">Background</a> — inject a background layer (colour, image, video, or live camera) behind any element within the forged element.</li><li>:material-palette: <a href="./sparks/theme">Theme</a> — apply a Frontend theme to the forged element or one of its descendants.</li></ul>',13)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
